"},{"path":"app.js","content":"(() => {
  'use strict';
  const ids=['a','b','c','d','e'];
  const descriptions={1:'Violin · glasses, light jacket',2:'Viola · pale long sleeves',3:'Cello · striped top',4:'Violin · light printed T-shirt',5:'Viola · red polo'};
  const nice={a:'Printed-shirt violin',b:'Cello',c:'Pale-shirt viola',d:'Glasses violin',e:'Red-polo viola'};
  const $=s=>document.querySelector(s);
  const scene=$('#scene'), seek=$('#seek'), playBtn=$('#play'), loopBox=$('#loop');
  let data=null, ctx=null, masterNode=null, buffers={}, gains={}, sources=[], playing=false, position=0, anchor=0, raf=0, activeCard=null, generation=0;
  const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
  function timeFmt(t){t=clamp(t,0,90);const m=Math.floor(t/60),s=t-m*60;return String(m).padStart(2,'0')+':'+s.toFixed(1).padStart(4,'0')}
  function makePerformers(){const host=$('#performers');host.innerHTML='';for(let slot=1;slot<=5;slot++){const tr=data.tracks.find(t=>t.slot===slot);const el=document.createElement('div');el.className='performer';el.dataset.role='performer';el.dataset.slot=slot;el.dataset.selected='false';el.innerHTML=`<div class="performer-top"><span class="slot">SLOT 0${slot}</span><span class="selected-chip">TARGET</span></div><strong>${descriptions[slot]}</strong><small>Track <span class="trackid">${tr.id.toUpperCase()}</span> · ${tr.instrument}</small>`;host.append(el)}}
  function makeGains(){const host=$('#gains');for(const id of ids){const t=data.tracks.find(x=>x.id===id);const div=document.createElement('div');div.className='gain-row';div.innerHTML=`<span class="gain-key">${id}</span><span class="gain-name">${nice[id]} <small>· slot ${t.slot}</small></span><input data-testid="gain-${id}" id="gain-${id}" aria-label="${nice[id]} gain" type="range" min="0" max="1" step="0.01" value="1"><output id="gainval-${id}">1.00</output>`;host.append(div);const input=div.querySelector('input');input.addEventListener('input',()=>{setGain(id,+input.value);$('#gainval-'+id).value=(+input.value).toFixed(2)})}}
  function makeCards(){const host=$('#cards'),track=$('#timeline-track');host.innerHTML='';track.innerHTML='';data.cards.forEach((c,i)=>{const card=document.createElement('article');card.className='rehearsal';card.dataset.role='rehearsal';card.dataset.cardId=c.id;const title=c.title;const selectedSlot=data.tracks.find(t=>t.id===c.target)?.slot;const gainSummary=ids.filter(k=>c.gains[k]>0).map(k=>k.toUpperCase()+' '+c.gains[k].toFixed(1)).join(' · ');card.innerHTML=`<div class="card-head"><div><div class="card-index">${c.id.toUpperCase()} / CUE 0${i+1}</div><div class="card-title">${title}</div></div><div class="card-time">${timeFmt(c.start)}–${timeFmt(c.end)}</div></div><div class="card-meta">Target <b>${c.target.toUpperCase()} · ${nice[c.target]}</b> &nbsp;|&nbsp; Slot ${selectedSlot}</div><p class="reason">${c.reason}</p><p class="uncertainty">Estimated boundaries; signal-derived note candidates can be split, merged or octave-shifted.</p><div class="card-bottom"><button class="rehearse-btn" data-testid="rehearse-${c.id}" type="button">▶ Rehearse this cue</button><span class="mix-summary">${gainSummary}<br>MASTER ${c.master.toFixed(2)}</span></div><div class="evidence-ids">EVIDENCE · ${c.evidence.map(x=>x.call).filter((x,j,a)=>a.indexOf(x)===j).join(' / ')}</div>`;card.querySelector('button').addEventListener('click',()=>applyCard(c));host.append(card);const marker=document.createElement('button');marker.type='button';marker.className='marker '+c.id;marker.style.left=(c.start/90*100)+'%';marker.style.width=((c.end-c.start)/90*100)+'%';marker.title=`${c.id.toUpperCase()} ${timeFmt(c.start)}–${timeFmt(c.end)} · target ${c.target.toUpperCase()}`;marker.setAttribute('aria-label',marker.title);marker.addEventListener('click',()=>applyCard(c));track.append(marker)})}
  function setGain(id,v){if(gains[id])gains[id].gain.setTargetAtTime(clamp(v,0,1),ctx.currentTime,.012)}
  function setMaster(v){if(masterNode)masterNode.gain.setTargetAtTime(clamp(v,0,1),ctx.currentTime,.012)}
  async function initAudio(){if(ctx)return;const AC=window.AudioContext||window.webkitAudioContext;if(!AC)throw Error('Web Audio is not supported by this browser.');ctx=new AC();masterNode=ctx.createGain();masterNode.gain.value=+$ ('#master').value;masterNode.connect(ctx.destination);for(const id of ids){gains[id]=ctx.createGain();gains[id].gain.value=1;gains[id].connect(masterNode)}const loaded=await Promise.all(ids.map(async id=>{const response=await fetch(`/media/track-${id}.wav`);if(!response.ok)throw Error(`Could not load track-${id}.wav`);buffers[id]=await ctx.decodeAudioData(await response.arrayBuffer())}));await ctx.resume()}
  function nowPosition(){if(!playing||!ctx)return position;return clamp(position+(ctx.currentTime-anchor),0,90)}
  function stopSources(){for(const s of sources){try{s.stop()}catch(_){}}sources=[]}
  function setVideo(t){if(!Number.isFinite(scene.duration)||!scene.src)return;const v=clamp(t,0,90);if(Math.abs(scene.currentTime-v)>.12){try{scene.currentTime=v}catch(_){}}}
  function schedule(t){stopSources();const gen=++generation;const when=ctx.currentTime+.035;for(const id of ids){const src=ctx.createBufferSource();src.buffer=buffers[id];src.connect(gains[id]);sources.push(src);src.start(when,t)}anchor=when;position=t;playing=true;playBtn.textContent='Ⅱ';playBtn.setAttribute('aria-label','Pause');$('#phase').textContent=activeCard?'Looping '+activeCard.toUpperCase():'Playing';scene.muted=true;scene.play().catch(()=>{});setVideo(t);sync()}
  function halt(keep=true){if(playing)position=nowPosition();playing=false;stopSources();cancelAnimationFrame(raf);playBtn.textContent='▶';playBtn.setAttribute('aria-label','Play');$('#phase').textContent=activeCard?'Cue '+activeCard.toUpperCase()+' · paused':'Paused';scene.pause();if(keep)setVideo(position);}
  function sync(){if(!playing)return;const t=nowPosition();const A=clamp(+$ ('#loop-start').value||0,0,90),B=clamp(+$ ('#loop-end').value||90,0,90);if(loopBox.checked&&B>A&&t>=B-.025){schedule(A);return}if(t>=90){halt();position=90;updateUI();return}position=t;updateUI();raf=requestAnimationFrame(sync)}
